import random as _random

class Full(int):
    def __mul__(self, other):
        if isinstance(other, Full):
            raise TypeError('quick_product multiplied the two full numbers')
        if isinstance(other, int):
            return Full(int(self) * other)
        return int(self) * other
    __rmul__ = __mul__

def _pairs():
    g = _random.Random(7)
    return [(g.randint(1000, 99999), g.randint(1000, 99999)) for _ in range(20)]

def quick_score():
    n = 0
    for a, b in _pairs():
        est = quick_product(Full(a), Full(b))
        if abs(est - a * b) <= 0.05 * a * b:
            n += 1
    return n

