def estimate_checker(items):
    out = []
    for (a, b), estimate in items:
        exact = a * b
        rel = (estimate - exact) / exact
        out.append((rel, abs(rel) <= 0.05))
    return out


def round_sig(x, n):
    return float(f'{x:.{n}g}')


def quick_product(a, b):
    # three significant figures each: at most about 0.5% off apiece
    return round_sig(a, 3) * round_sig(b, 3)

