widget.solution:
def combine(changes):
    factor = 1.0
    for p in changes:
        factor *= 1 + p / 100
    return (factor - 1) * 100


def rate_change(old, new):
    points = new - old
    percent = None if old == 0 else 100 * points / old
    return points, percent
